sql.where:


    and ss.createdat >= str_to_date(#{startDate}, '%Y-%m-%d')


    and ss.createdat <= str_to_date(concat(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')




    and upper(ss.servicename) like concat('%', upper(#{serviceNameKeyword}), '%')




    and ss.memnum = #{memNum}




    and ss.empnum = #{empNum}


and ss.status = 'ACTIVE'
